import axios from "axios";
import type { Request, Response } from "express";
import dotenv from "dotenv";
import { geminiModel, type ChatMessage } from "./gemini.js";
import Classification from "../Algos/classAlgo.js";
import type { Product } from "../products/types.js";
// 👇 تأكد أن المسار هنا يطابق مكان ملف المودل عندك
import ChatModel from "../DB/chatModel.js";

dotenv.config();

type Languages = "en_US" | "ar_SA";

interface WhatsAppMessagePayload {
    messaging_product: "whatsapp";
    recipient_type?: "individual";
    to: string;
    type:
        | "text"
        | "template"
        | "interactive"
        | "image"
        | "document"
        | "audio"
        | "video"
        | "sticker"
        | "location";
    text?: {
        preview_url?: boolean;
        body: string;
    };
    template?: {
        name: string;
        language: {
            code: Languages;
        };
    };
    image?: {
        link: string;
        caption?: string;
        filename?: string;
        provider?:
            | "whatsapp"
            | "facebook"
            | "instagram"
            | "messenger"
            | "telegram";
        id?: string;
    };
}

class WhatsApp {
    private WHATS_APP_PHONE_NUMBER_ID = process.env.WHATS_APP_PHONE_NUMBER_ID;
    private WHATSAPP_TOKEN = process.env.WHATSAPP_TOKEN;
    private VERIFY_TOKEN = process.env.VERIFY_TOKEN;

    public constructor(
        WHATS_APP_PHONE_NUMBER_ID?: string,
        WHATSAPP_TOKEN?: string,
        VERIFY_TOKEN?: string,
    ) {
        this.WHATS_APP_PHONE_NUMBER_ID = WHATS_APP_PHONE_NUMBER_ID;
        this.WHATSAPP_TOKEN = WHATSAPP_TOKEN;
        this.VERIFY_TOKEN = VERIFY_TOKEN;
    }

    public async SendMsg(payload: WhatsAppMessagePayload) {
        const url = `https://graph.facebook.com/v21.0/${this.WHATS_APP_PHONE_NUMBER_ID}/messages`;
        try {
            await axios.post(url, payload, {
                headers: {
                    Authorization: `Bearer ${this.WHATSAPP_TOKEN}`,
                    "Content-Type": "application/json",
                },
            });
        } catch (error: any) {
            if (axios.isAxiosError(error)) {
                console.error(
                    "❌ API Error:",
                    error.response?.data || error.message,
                );
            } else {
                console.error("❌ Unexpected Error:", error);
            }
        }
    }

    public async GetWebHook(obj: WhatsApp, req: Request, res: Response) {
        const mode = req.query["hub.mode"];
        const token = req.query["hub.verify_token"];
        const challenge = req.query["hub.challenge"];

        if (mode && token) {
            if (mode === "subscribe" && token === obj.VERIFY_TOKEN) {
                console.log("WEBHOOK_VERIFIED");
                res.status(200).send(challenge);
            } else {
                res.sendStatus(403);
            }
        } else {
            res.sendStatus(400);
        }
    }

    public async PostWebHook(obj: WhatsApp, req: Request, res: Response) {
        if (!req.body.object) {
            res.sendStatus(404);
            return;
        }
        const entry = req.body.entry?.[0];
        const changes = entry?.changes?.[0];
        const value = changes?.value;
        const message = value?.messages?.[0];

        // ============================================================
        //  معالجة الرسائل النصية (Text Messages)
        // ============================================================
        if (message && message.type === "text") {
            const from = message.from;
            const incomingText = message.text.body;
            console.log(`📩 New Message from ${from}: ${incomingText}`);

            try {
                // 1. جلب بيانات المستخدم من قاعدة البيانات
                let userRecord = await ChatModel.findOne({
                    where: { phone: from },
                });

                // 2. تجهيز الشات والمنتج الحالي (للسياق)
                // إذا لم يكن هناك سجل، نستخدم مصفوفة فارغة
                const currentChat: ChatMessage[] = userRecord
                    ? userRecord.chat
                    : [];
                const currentProduct: Product | undefined = userRecord?.product;

                let aiMsg = null;

                // 3. التصنيف (Using existing logic)
                const classification = await Classification.Search(
                    incomingText,
                    currentChat,
                );

                // 4. التوجيه بناءً على التصنيف
                if (
                    classification.category == "question_about_previous_product"
                ) {
                    aiMsg = await Classification.QuestionAboutPreviousProduct(
                        incomingText,
                        currentChat,
                        currentProduct!, // يفترض وجود منتج سابق هنا
                    );
                } else if (
                    classification.category == "question_about_new_product"
                ) {
                    aiMsg = await Classification.QustionAboutNewProduct(
                        incomingText,
                        currentChat,
                    );
                } else if (classification.category == "global_questions") {
                    aiMsg = await Classification.GlobalQuestions(
                        incomingText,
                        currentChat,
                        currentProduct!,
                    );
                } else if (classification.category == "order_question") {
                    aiMsg = await Classification.OrderQuestion(
                        incomingText,
                        currentChat,
                        currentProduct!,
                    );
                } else if (classification.category == "order_confirmation") {
                    aiMsg = await Classification.OrderConfirmation(
                        incomingText,
                        currentChat,
                        currentProduct!,
                    );
                }

                // استخراج الرد والمنتج الجديد (إن وجد)
                const responseText = (aiMsg as any).msg;
                const newProduct = (aiMsg as any).product;

                // 5. حفظ البيانات في قاعدة البيانات
                const userMessageItem: ChatMessage = {
                    role: "user",
                    parts: [{ text: incomingText }],
                };
                const modelMessageItem: ChatMessage = {
                    role: "model",
                    parts: [{ text: responseText }],
                };

                if (!userRecord) {
                    // --- إنشاء مستخدم جديد ---
                    await ChatModel.create({
                        phone: from,
                        chat: [userMessageItem, modelMessageItem],
                        product: newProduct,
                    });
                } else {
                    // --- تحديث مستخدم موجود ---
                    // نقوم بفك المصفوفة القديمة وإضافة الجديد لضمان تحديث الـ JSON
                    const updatedChat = [
                        ...userRecord.chat,
                        userMessageItem,
                        modelMessageItem,
                    ];

                    await userRecord.update({
                        chat: updatedChat,
                        // نحدث المنتج إذا جاء منتج جديد، وإلا نبقي القديم
                        product: newProduct || userRecord.product,
                    });
                }

                // 6. إرسال الرد للواتساب
                obj.SendMsg(SendedData.SendMessagetData(responseText, from));
                console.log("SENDING MESSAGE");
                res.sendStatus(200);
            } catch (error) {
                console.error("Failed to reply:", error);
                res.sendStatus(200);
            }

            // ============================================================
            //  معالجة الصور (Image Messages)
            // ============================================================
        } else if (message && message.type === "image") {
            const from = message.from;

            try {
                // 1. جلب المستخدم والسياق
                let userRecord = await ChatModel.findOne({
                    where: { phone: from },
                });
                const currentChat: ChatMessage[] = userRecord
                    ? userRecord.chat
                    : [];

                const imageId = message.image.id;

                // --- تحميل الصورة ---
                const metadataUrl = `https://graph.facebook.com/v21.0/${imageId}`;
                const metadataResponse = await axios.get(metadataUrl, {
                    headers: { Authorization: `Bearer ${obj.WHATSAPP_TOKEN}` },
                });

                const actualImageUrl = metadataResponse.data.url;
                const mimeType =
                    metadataResponse.data.mime_type || "image/jpeg";

                const imageResponse = await axios.get(actualImageUrl, {
                    responseType: "arraybuffer",
                    headers: { Authorization: `Bearer ${obj.WHATSAPP_TOKEN}` },
                });

                const base64Image = Buffer.from(imageResponse.data).toString(
                    "base64",
                );
                const imageInput = { mimeType: mimeType, data: base64Image };

                // --- إرسال لـ Gemini ---
                const dataWithImage = await geminiModel.SendMessage({
                    prompt: "اعطني رقم المعرف اللي في الصورة فقط",
                    history: currentChat,
                    image: imageInput,
                });

                // --- معالجة الرد عبر الخوارزمية ---
                const aiMsg = await Classification.QustionAboutNewProduct(
                    dataWithImage,
                    currentChat,
                );

                // --- إرسال الرد للواتساب ---
                obj.SendMsg(SendedData.SendMessagetData(aiMsg.msg, from));

                // --- الحفظ في قاعدة البيانات ---
                // ملاحظة: نفترض هنا أن aiMsg يحتوي على البرومبت الأصلي أو الوصف
                const promptText = aiMsg.prompt || "Image Request";

                const userMsgObj: ChatMessage = {
                    role: "user",
                    parts: [{ text: promptText }],
                };
                const modelMsgObj: ChatMessage = {
                    role: "model",
                    parts: [{ text: aiMsg.msg }],
                };

                if (!userRecord) {
                    await ChatModel.create({
                        phone: from,
                        chat: [userMsgObj, modelMsgObj],
                        product: aiMsg.product || null,
                    });
                } else {
                    const updatedChat = [
                        ...userRecord.chat,
                        userMsgObj,
                        modelMsgObj,
                    ];
                    await userRecord.update({
                        chat: updatedChat,
                        product: aiMsg.product || userRecord.product || null,
                    });
                }

                res.sendStatus(200);
            } catch (error) {
                console.error("Error processing image:", error);
                res.sendStatus(200);
            }
        }
    }
}

export const whatsApp = new WhatsApp(
    process.env.WHATS_APP_PHONE_NUMBER_ID,
    process.env.WHATSAPP_TOKEN,
    process.env.VERIFY_TOKEN,
);

export class SendedData {
    public static SendMessagetData(message: string, phoneNumber: string) {
        const data: WhatsAppMessagePayload = {
            messaging_product: "whatsapp",
            recipient_type: "individual",
            to: phoneNumber,
            type: "text",
            text: {
                body: message,
            },
        };
        return data;
    }

    public static SendImageLinktData(
        link: string,
        phoneNumber: string,
        caption: string,
    ) {
        const data: WhatsAppMessagePayload = {
            messaging_product: "whatsapp",
            recipient_type: "individual",
            to: phoneNumber,
            type: "image",
            image: {
                link: link,
                caption,
            },
        };
        return data;
    }

    public static SendImageFiletData(filPath: string, phoneNumber: string) {}

    public static T_hello_world(phoneNumber: string, lang: Languages) {
        const data: WhatsAppMessagePayload = {
            messaging_product: "whatsapp",
            recipient_type: "individual",
            to: phoneNumber,
            type: "template",
            template: {
                name: "hello_world",
                language: {
                    code: lang,
                },
            },
        };
        return data;
    }
}

