import axios, { type AxiosResponse } from "axios";
import dotenv from "dotenv";
dotenv.config();

interface ImageInput {
    mimeType: string;
    data: string; // base64-encoded image data
}

export interface ChatMessage {
    role: "user" | "model";
    parts: {
        text?: string;
        inlineData?: ImageInput;
    }[];
}

class GeminiModel {
    private apiKey: string = process.env.GEMINI_API_KEY || "";
    private modelName = "gemini-2.5-flash";
    public async SendMessage({
        prompt,
        image,
        history,
    }: {
        prompt: string;
        history?: ChatMessage[];
        image?: ImageInput;
    }): Promise<string> {
        const GEMINI_API_URL = `https://generativelanguage.googleapis.com/v1beta/models/${this.modelName}:generateContent?key=${this.apiKey}`;
        const currentParts: any[] = [{ text: prompt }];

        if (image) {
            currentParts.push({
                inlineData: { mimeType: image.mimeType, data: image.data },
            });
        }

        const currentUserMessage: ChatMessage = {
            role: "user",
            parts: currentParts,
        };

        // 4. Combine History + Current Message
        // The API expects an array of objects: [{role: "user"...}, {role: "model"...}, {role: "user"...}]
        const fullConversation = [...(history || []), currentUserMessage];

        const body = {
            contents: fullConversation,
        };
        try {
            let response: AxiosResponse<any, any, {}>;
            if (typeof prompt == "string") {
                response = await axios.post(GEMINI_API_URL, body);
            }

            const text =
                response!.data.candidates?.[0]?.content?.parts?.[0]?.text;
            return text;
        } catch (error: any) {
            console.error(
                "Error calling Gemini API:",
                error.response?.data || error.message,
            );
            return "";
        }
    }
}

export const geminiModel = new GeminiModel();

