import axios, {} from "axios";
import dotenv from "dotenv";
dotenv.config();
class GeminiModel {
    apiKey = process.env.GEMINI_API_KEY || "";
    modelName = "gemini-2.5-flash";
    async SendMessage({ prompt, image, history, }) {
        const GEMINI_API_URL = `https://generativelanguage.googleapis.com/v1beta/models/${this.modelName}:generateContent?key=${this.apiKey}`;
        const currentParts = [{ text: prompt }];
        if (image) {
            currentParts.push({
                inlineData: { mimeType: image.mimeType, data: image.data },
            });
        }
        const currentUserMessage = {
            role: "user",
            parts: currentParts,
        };
        // 4. Combine History + Current Message
        // The API expects an array of objects: [{role: "user"...}, {role: "model"...}, {role: "user"...}]
        const fullConversation = [...(history || []), currentUserMessage];
        const body = {
            contents: fullConversation,
        };
        try {
            let response;
            if (typeof prompt == "string") {
                response = await axios.post(GEMINI_API_URL, body);
            }
            const text = response.data.candidates?.[0]?.content?.parts?.[0]?.text;
            return text;
        }
        catch (error) {
            console.error("Error calling Gemini API:", error.response?.data || error.message);
            return "";
        }
    }
}
export const geminiModel = new GeminiModel();
